mapper.select:
select order by (t.revoked_at is not null),
t.terminal_nm desc t.plant_cd desc t.terminal_type desc t.last_seen_at desc nulls last t.terminal_cd desc ,
t.terminal_id limit #{page.size} offset #{page.offset}

mapper.update:
update sys_terminal
   set key_hash = #{keyHash}, activated_at = now(), row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where terminal_id = #{id} and revoked_at is null and terminal_type = 'COLLECTOR'

mapper.select:
select l.detail from sys_access_log l
 where l.event_cd = 'POP_KIOSK_EXIT' and l.result_cd = 'OK' and l.login_id = #{actor}
   and l.occurred_at > now() - interval '1 hour'
   and right(l.detail, length(#{needle})) = #{needle}
 order by l.log_id desc
 limit 1

select wp.wo_proc_id, w.wo_id, w.wo_no, i.item_cd, i.item_nm, trim_scale(w.plan_qty)::text as plan_qty, w.unit_cd, w.priority, w.plan_start, w.status as wo_status, wp.op_seq, wp.proc_id, wp.proc_cd, wp.proc_nm, h.node_cd, wp.status as proc_status, e.equip_cd, e.equip_nm from prd_wo_proc wp join prd_wo w on w.wo_id = wp.wo_id join mst_item i on i.item_id = w.item_id left join mst_equip_hier h on h.node_id = wp.node_id left join mst_equip e on e.equip_id = wp.equip_id where w.plant_cd = #{plantCd} and w.status in ('RELEASED', 'IN_PROGRESS') and wp.status <> 'DONE'
and (wp.node_id = #{nodeId} or wp.node_id in (select c.node_id from mst_equip_hier c where c.parent_id = #{nodeId}))
order by w.priority, w.plan_start, w.wo_no, wp.op_seq limit #{limit}
